attempts.raw_output:
{
  "motion_interpretation": "Kiến nghị yêu cầu nhà trường cấm hoàn toàn học sinh mang và sử dụng điện thoại di động trong thời gian học và trong khuôn viên trường, ngoại trừ các trường hợp được giáo viên cho phép đặc biệt.",
  "definitions": [
    {
      "term": "điện thoại di động",
      "meaning": "Thiết bị điện tử cá nhân cho phép thực hiện cuộc gọi, nhắn tin và truy cập internet, thường được mang theo người."
    }
  ],
  "arguments": [
    {
      "id": "A1",
      "title": "Giảm mất tập trung",
      "claim": "Cấm điện thoại giúp học sinh tập trung hơn vào bài học.",
      "reasoning": "Khi không có điện thoại, học sinh không bị cuốn vào tin nhắn, mạng xã hội hay trò chơi, do đó thời gian suy nghĩ và ghi chú trên lớp tăng lên.",
      "example": "Giả sử một lớp học 10A không cho phép học sinh mang điện thoại vào lớp, các em sẽ chỉ nghe giảng và ghi chép, thay vì liên tục kiểm tra điện thoại giữa giờ.",
      "impact": "Sự tập trung tăng sẽ cải thiện kết quả học tập và giảm thời gian học lại."
    },
    {
      "id": "A2",
      "title": "Bảo vệ môi trường học tập an toàn",
      "claim": "Cấm điện thoại giảm thiểu các hành vi gây rối và bảo vệ an ninh trường học.",
      "reasoning": "Không có điện thoại, học sinh không thể chụp ảnh, quay video hoặc gửi tin nhắn gây xôn xao, đồng thời giảm nguy cơ bắt nạt qua mạng trong khuôn viên trường.",
      "example": "Giả sử trường trung học X không cho phép điện thoại, học sinh không thể chụp ảnh người khác mà không có sự cho phép, giảm các tranh cãi và vụ việc bắt nạt trực tuyến trong giờ ra chơi.",
      "impact": "Môi trường học tập trở nên lành mạnh hơn, giảm căng thẳng và các sự cố kỷ luật."
